using CashFlow.Launch.Domain.Entities;using CashFlow.Launch.Domain.Enums;using CashFlow.Launch.Domain.Interfaces;using CashFlow.Launch.Domain.Interfaces.Services;using CashFlow.Launch.Domain.Models;
namespace CashFlow.Launch.Domain.Services;
public class CreditCardService:ICreditCardService{private readonly ICreditCardRepository _cardRepository;private readonly ICreditCardPurchaseRepository _purchaseRepository;private readonly ICreditCardInstallmentRepository _installmentRepository;private readonly ICategoryRepository _categoryRepository;public CreditCardService(ICreditCardRepository c,ICreditCardPurchaseRepository p,ICreditCardInstallmentRepository i,ICategoryRepository cat){_cardRepository=c;_purchaseRepository=p;_installmentRepository=i;_categoryRepository=cat;}private static bool Valid(string n,decimal l,int c,int d)=>!string.IsNullOrWhiteSpace(n)&&l>=0&&c is>=1 and<=28&&d is>=1 and<=28;public async Task<CreditCard?>CreateCardAsync(string n,decimal l,int c,int d){if(!Valid(n,l,c,d))return null;var x=new CreditCard{Name=n.Trim(),Limit=l,ClosingDay=c,DueDay=d};await _cardRepository.AddAsync(x);await _cardRepository.SaveChangesAsync();return x;}public async Task<CreditCard?>UpdateCardAsync(Guid id,string n,decimal l,int c,int d){var x=await _cardRepository.GetByIdAsync(id);if(x is null||!Valid(n,l,c,d))return null;x.Name=n.Trim();x.Limit=l;x.ClosingDay=c;x.DueDay=d;_cardRepository.Update(x);await _cardRepository.SaveChangesAsync();return x;}public async Task<bool>DeleteCardAsync(Guid id){var x=await _cardRepository.GetByIdAsync(id);if(x is null)return false;x.IsActive=false;_cardRepository.Update(x);await _cardRepository.SaveChangesAsync();return true;}public Task<List<CreditCard>>GetCardsAsync()=>_cardRepository.GetAllAsync();public async Task<CreditCardPurchase?>CreatePurchaseAsync(Guid cardId,Guid? catId,string desc,decimal total,int count,DateTime date){var card=await _cardRepository.GetByIdAsync(cardId);if(card is null||string.IsNullOrWhiteSpace(desc)||total<=0||count<1||count>120)return null;if(catId.HasValue){var cat=await _categoryRepository.GetByIdAsync(catId.Value);if(cat is null||cat.Type!=EntryType.Debit)return null;}date=DateTime.SpecifyKind(date,DateTimeKind.Utc);var p=new CreditCardPurchase{CreditCardId=cardId,CategoryId=catId,Description=desc.Trim(),TotalAmount=total,InstallmentsCount=count,PurchaseDate=date};await _purchaseRepository.AddAsync(p);var baseAmount=Math.Floor((total/count)*100m)/100m;var first=First(date,card.ClosingDay);for(var n=1;n<=count;n++){var reference=first.AddMonths(n-1);await _installmentRepository.AddAsync(new CreditCardInstallment{CreditCardPurchaseId=p.Id,Number=n,Amount=n==count?total-baseAmount*(count-1):baseAmount,ReferenceDate=reference,DueDate=Due(reference,card.ClosingDay,card.DueDay)});}await _purchaseRepository.SaveChangesAsync();return p;}public async Task<bool>DeletePurchaseAsync(Guid id){var p=await _purchaseRepository.GetByIdAsync(id);if(p is null)return false;var all=await _installmentRepository.GetAllAsync();foreach(var i in all.Where(x=>x.CreditCardPurchaseId==id))_installmentRepository.Remove(i);_purchaseRepository.Remove(p);await _purchaseRepository.SaveChangesAsync();return true;}public async Task<CreditCardInvoiceSummary?>GetInvoiceAsync(Guid id,int y,int m){var card=await _cardRepository.GetByIdAsync(id);if(card is null||m is<1 or>12)return null;var items=await _installmentRepository.GetByCardAndReferenceAsync(id,y,m);var reference=new DateTime(y,m,1,0,0,0,DateTimeKind.Utc);return new CreditCardInvoiceSummary{CreditCardId=card.Id,CreditCardName=card.Name,Year=y,Month=m,DueDate=Due(reference,card.ClosingDay,card.DueDay),TotalAmount=items.Sum(x=>x.Amount),PaidAmount=items.Where(x=>x.IsPaid).Sum(x=>x.Amount),Items=items.Select(x=>new CreditCardInvoiceItem{InstallmentId=x.Id,PurchaseId=x.CreditCardPurchaseId,Description=x.CreditCardPurchase?.Description??string.Empty,InstallmentNumber=x.Number,InstallmentsCount=x.CreditCardPurchase?.InstallmentsCount??0,Amount=x.Amount,IsPaid=x.IsPaid,CategoryId=x.CreditCardPurchase?.CategoryId}).ToList()};}public async Task<bool>MarkInstallmentPaidAsync(Guid id){var x=await _installmentRepository.GetByIdAsync(id);if(x is null)return false;x.IsPaid=true;_installmentRepository.Update(x);await _installmentRepository.SaveChangesAsync();return true;}private static DateTime First(DateTime d,int close){var m=new DateTime(d.Year,d.Month,1,0,0,0,DateTimeKind.Utc);return d.Day<=close?m:m.AddMonths(1);}private static DateTime Due(DateTime r,int close,int due){var m=due>close?r:r.AddMonths(1);return new DateTime(m.Year,m.Month,due,0,0,0,DateTimeKind.Utc);}}
